   110    bool resize ()
   111    {
   112      if (unlikely (!successful)) return false;
   113
   114      unsigned int power = hb_bit_storage (population * 2 + 8);
   115      unsigned int new_size = 1u << power;
   116      item_t *new_items = (item_t *) malloc ((size_t) new_size * sizeof (item_t));
   117      if (unlikely (!new_items))
   118      {
   119        successful = false;
   120        return false;
   121      }
   122      + hb_iter (new_items, new_size)
   123      | hb_apply (&item_t::clear)
   124      ;
   125
   126      unsigned int old_size = mask + 1;
   127      item_t *old_items = items;
   128
   129      /* Switch to new, empty, array. */
   130      population = occupancy = 0;
   131      mask = new_size - 1;
   132      prime = prime_for (power);
   133      items = new_items;
   134
   135      /* Insert back old items. */
   136      if (old_items)
   137        for (unsigned int i = 0; i < old_size; i++)
   138          if (old_items[i].is_real ())
   139            set (old_items[i].key, old_items[i].value);
   140
   141      free (old_items);
   142
   143      return true;
   144    }
