   146    void set (K key, V value)
   147    {
   148      if (unlikely (!successful)) return;
   149      if (unlikely (key == kINVALID)) return;
   150      if ((occupancy + occupancy / 2) >= mask && !resize ()) return;
   151      unsigned int i = bucket_for (key);
   152
   153      if (value == vINVALID && items[i].key != key)
   154        return; /* Trying to delete non-existent key. */
   155
   156      if (!items[i].is_unused ())
   157      {
   158        occupancy--;
   159        if (items[i].is_tombstone ())
   160          population--;
   161      }
   162
   163      items[i].key = key;
   164      items[i].value = value;
   165
   166      occupancy++;
   167      if (!items[i].is_tombstone ())
   168        population++;
   169
   170    }
   171    V get (K key) const
   172    {
   173      if (unlikely (!items)) return vINVALID;
   174      unsigned int i = bucket_for (key);
   175      return items[i].is_real () && items[i] == key ? items[i].value : vINVALID;
   176    }
   177
   178    void del (K key) { set (key, vINVALID); }
